def emulate_escape_rule(fm_text):
    """Mimic the Linter's escape rule as diagnosed: for a 'key: value' line whose UNQUOTED value has ' or \" or ': ',
    wrap that single line's value in double quotes. It never touches continuation lines."""
    out=[]
    for l in fm_text.split("\n"):
        m=re.match(r"^(\s*[\w.-]+):\s+(.*)$",l)
        if m:
            k,v=m.groups()
            if v and v[0] not in "'\"[{|>&*!" and re.search(r"['\"]|: ",v):
                v='"'+v.replace('\\','\\\\').replace('"','\\"')+'"' if False else '"'+v+'"'   # naive wrap, as observed in the reported error text
                l=f"{k}: {v}"
        out.append(l)
    return "\n".join(out)

def check(d,label):
    bad=[]
    for f in mine(d):
        s=open(os.path.join(d,f),encoding="utf-8").read()
        fm=re.match(r"---\n(.*?)\n---\n",s,re.S).group(1)
        try: yaml.safe_load(fm)
        except Exception as e: bad.append((f,"raw-yaml",str(e).split("\n")[0][:60])); continue
